//! Instruction counts of the classic kernels (ADR-0025 PR gate, gungraun):
//! the CartPole physics step, and one full pool step (auto-reset on,
//! observation writing included) for CartPole and Tag, and one CartPole
//! step in steady state. Setup runs outside
//! the measured region, and the pool benchmarks return their inputs so
//! that dropping them is not counted either. Linux only (Valgrind); see `make gungraun`.

#![expect(clippy::unwrap_used, reason = "bench setup unwraps")]
#![expect(missing_docs, reason = "items generated by the gungraun macros")]

use core::num::NonZeroU32;
use std::hint::black_box;

use gungraun::{
    Callgrind, CallgrindMetrics, LibraryBenchmarkConfig, library_benchmark,
    library_benchmark_group, main,
};
use tessera_rl_classic::cartpole::physics;
use tessera_rl_classic::{CartPole, CartPoleConfig, Tag, TagConfig};
use tessera_rl_engine::{ActionInput, EnvPool, Masked, NoMasks, PoolOptions, Reseed};
use tessera_rl_num::identity::Seed;

fn options(n: u32) -> PoolOptions {
    let mut o = PoolOptions::new(NonZeroU32::new(n).unwrap(), Seed::new(1));
    o.max_episode_steps = NonZeroU32::new(500);
    o
}

/// A reset CartPole pool and one batch of alternating actions.
fn cartpole(n: u32) -> (EnvPool<CartPole, NoMasks>, Vec<i32>) {
    let mut pool = EnvPool::new(CartPoleConfig::default(), options(n)).unwrap();
    pool.reset_all(Reseed::Keep).unwrap();
    (pool, (0..n).map(|i| i32::from(i % 2 == 0)).collect())
}

/// Settling steps before the steady-state measurement: enough that most
/// episodes have reset at least once (untrained CartPole episodes last tens of
/// steps), so the measured step carries a steady mix of resets.
const SETTLE_STEPS: usize = 300;

/// xorshift64: a fixed pseudo-random action stream, independent of the engine.
fn xorshift(s: &mut u64) -> u64 {
    *s ^= *s << 13;
    *s ^= *s >> 7;
    *s ^= *s << 17;
    *s
}

/// Steps measured by the steady-state kernel (freeze r4).
const MEASURED_STEPS: usize = 64;

/// A CartPole pool in steady state, and the next `MEASURED_STEPS` batches of
/// random actions, all drawn here so the generator is not measured.
/// It resets, then takes `SETTLE_STEPS` steps with a fixed xorshift action
/// sequence, all outside the measured region. Every input is fixed, so the
/// state reached is the same on every run.
fn cartpole_steady(n: u32) -> (EnvPool<CartPole, NoMasks>, Vec<Vec<i32>>) {
    let mut pool = EnvPool::new(CartPoleConfig::default(), options(n)).unwrap();
    pool.reset_all(Reseed::Keep).unwrap();
    let mut seed = 0x9e37_79b9_7f4a_7c15_u64;
    let mut row = || -> Vec<i32> {
        (0..n)
            .map(|_| i32::from(xorshift(&mut seed) & 1 == 1))
            .collect()
    };
    for _ in 0..SETTLE_STEPS {
        let actions = row();
        pool.step(ActionInput {
            discrete: &actions,
            continuous: &[],
        })
        .unwrap();
    }
    let rows = (0..MEASURED_STEPS).map(|_| row()).collect();
    (pool, rows)
}

/// A reset Tag pool and one batch of moves (illegal ones become no-ops).
fn tag(n: u32) -> (EnvPool<Tag, Masked>, Vec<i32>) {
    let mut pool = EnvPool::with_masks(TagConfig::default(), options(n)).unwrap();
    pool.reset_all(Reseed::Keep).unwrap();
    let rows = pool.outputs().unwrap().rewards().len();
    (
        pool,
        (0..rows).map(|i| i32::try_from(i % 5).unwrap()).collect(),
    )
}

#[library_benchmark]
#[bench::steps_1000([0.01, 0.0, 0.02, 0.0])]
fn cartpole_physics(start: [f64; 4]) -> [f64; 4] {
    let mut s = start;
    for k in 0..1000 {
        s = physics::step(black_box(s), k % 2 == 0);
        black_box(physics::is_terminal(s));
    }
    s
}

#[library_benchmark]
#[bench::n1024(setup = cartpole, args = (1024))]
fn cartpole_pool_step(
    (mut pool, actions): (EnvPool<CartPole, NoMasks>, Vec<i32>),
) -> (EnvPool<CartPole, NoMasks>, Vec<i32>) {
    let out = pool
        .step(ActionInput {
            discrete: black_box(&actions),
            continuous: &[],
        })
        .unwrap();
    black_box(out.rewards().first().copied());
    (pool, actions)
}

// `MEASURED_STEPS` steps of a CartPole pool in steady state (see
// `cartpole_steady`), with random actions drawn in setup: the per-instance step
// cost with resets mixed in over many steps, which a fresh pool's first step
// does not show.
#[library_benchmark]
#[bench::n1024(setup = cartpole_steady, args = (1024))]
fn cartpole_pool_steady(
    (mut pool, rows): (EnvPool<CartPole, NoMasks>, Vec<Vec<i32>>),
) -> (EnvPool<CartPole, NoMasks>, Vec<Vec<i32>>) {
    for actions in &rows {
        let out = pool
            .step(ActionInput {
                discrete: black_box(actions),
                continuous: &[],
            })
            .unwrap();
        black_box(out.rewards().first().copied());
    }
    (pool, rows)
}

#[library_benchmark]
#[bench::n256(setup = tag, args = (256))]
fn tag_pool_step(
    (mut pool, actions): (EnvPool<Tag, Masked>, Vec<i32>),
) -> (EnvPool<Tag, Masked>, Vec<i32>) {
    let out = pool
        .step(ActionInput {
            discrete: black_box(&actions),
            continuous: &[],
        })
        .unwrap();
    black_box(out.rewards().first().copied());
    (pool, actions)
}

library_benchmark_group!(
    name = classic,
    benchmarks = [
        cartpole_physics,
        cartpole_pool_step,
        cartpole_pool_steady,
        tag_pool_step
    ]
);

/// The glibc dispatch pin of every instruction-count run.
const GLIBC_TUNABLES: &str = include_str!("../../../benches/gungraun/GLIBC_TUNABLES");

/// Callgrind with the cache simulation on (instruction counts and cache
/// misses, ADR-0025). The gate, a 2% limit on `Ir`, is passed by
/// `scripts/gungraun.sh`; the cache metrics are reported.
fn config() -> LibraryBenchmarkConfig {
    let mut config = LibraryBenchmarkConfig::default();
    // glibc picks memcpy and memset variants by CPU (ifunc), which would
    // make the counts depend on the machine: pin them to the baseline
    // variants (benches/gungraun/README.md).
    config.env("GLIBC_TUNABLES", GLIBC_TUNABLES.trim());
    config.tool(
        // A fixed cache geometry, so cache metrics compare across hosts.
        Callgrind::with_args([
            "--cache-sim=yes",
            "--I1=32768,8,64",
            "--D1=32768,8,64",
            "--LL=8388608,16,64",
        ])
        .format([CallgrindMetrics::All]),
    );
    config
}

main!(config = config(), library_benchmark_groups = classic);
